{"tool": "sql", "args": {"query": "SELECT SUM(CASE WHEN Cell_architecture='nip' THEN 1 ELSE 0 END) AS nip_all_etl, SUM(CASE WHEN Cell_architecture='nip' AND ETL_stack_sequence LIKE '%SnO2%' THEN 1 ELSE 0 END) AS nip_sno2, SUM(CASE WHEN Cell_architecture='nip' AND ETL_stack_sequence LIKE '%TiO2%' THEN 1 ELSE 0 END) AS nip_tio2, SUM(CASE WHEN Cell_architecture='nip' AND ETL_stack_sequence NOT LIKE '%SnO2%' AND ETL_stack_sequence NOT LIKE '%TiO2%' THEN 1 ELSE 0 END) AS nip_other_etl, COUNT(DISTINCT CASE WHEN ETL_stack_sequence LIKE '%SnO2%' AND Cell_architecture='nip' THEN Ref_DOI_number END) AS nip_sno2_papers, COUNT(DISTINCT CASE WHEN ETL_stack_sequence LIKE '%TiO2%' AND Cell_architecture='nip' THEN Ref_DOI_number END) AS nip_tio2_papers, SUM(CASE WHEN ETL_stack_sequence LIKE '%SnO2%' AND Cell_architecture='nip' AND JV_default_PCE IS NOT NULL AND JV_default_PCE>0 THEN 1 ELSE 0 END) AS nip_sno2_with_pce, AVG(CASE WHEN ETL_stack_sequence LIKE '%SnO2%' AND Cell_architecture='nip' THEN JV_default_PCE END) AS avg_pce_all_sno2_nip FROM devices"}}
{"tool": "sql", "args": {"query": "SELECT Ref_DOI_number, Ref_lead_author, Ref_journal, Ref_publication_date, COUNT(*) n_rec, COUNT(DISTINCT ETL_additives_compounds) n_additive, GROUP_CONCAT(DISTINCT ETL_additives_compounds) additives, GROUP_CONCAT(DISTINCT ETL_stack_sequence) etl_stacks FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND Cell_architecture='nip' GROUP BY Ref_DOI_number HAVING COUNT(DISTINCT ETL_additives_compounds) BETWEEN 2 AND 6 ORDER BY n_rec DESC LIMIT 25"}}
{"tool": "sql", "args": {"query": "SELECT ETL_stack_sequence, COUNT(*) n_dev, COUNT(DISTINCT Ref_DOI_number) n_papers, ROUND(AVG(JV_default_PCE),2) avg_pce, MAX(JV_default_PCE) max_pce FROM devices WHERE ETL_stack_sequence LIKE '%SnO2%' AND Cell_architecture='nip' GROUP BY ETL_stack_sequence ORDER BY n_dev DESC LIMIT 20"}}
